const body = $json.body || $json;
const entry = body && body.entry && body.entry[0];
if (!entry) return [];

const messaging = entry.messaging && entry.messaging[0];
const change = entry.changes && entry.changes[0];

// ── Messenger direct message (incoming or echo) ──
if (messaging) {
  const msg = messaging.message || {};
  const isEcho = !!(msg && msg.is_echo);

  // Meta ID Swap Fix:
  // - Echo message (sent by merchant on Meta Business Suite/Facebook):
  //   sender = PAGE_ID, recipient = CUSTOMER_PSID
  // - Incoming message (sent by customer):
  //   sender = CUSTOMER_PSID, recipient = PAGE_ID
  const customerPsid = isEcho
    ? (messaging.recipient && messaging.recipient.id)
    : (messaging.sender && messaging.sender.id);

  const pageId = entry.id || (isEcho ? (messaging.sender && messaging.sender.id) : (messaging.recipient && messaging.recipient.id));

  if (!customerPsid) return [];

  let userMessage = msg.text || '';
  let mediaType = 'text';
  let mediaUrl = '';
  const att = msg.attachments && msg.attachments[0];
  if (att && att.type === 'image') {
    mediaType = 'image';
    mediaUrl = (att.payload && att.payload.url) || '';
  } else if (att && att.type === 'audio') {
    mediaType = 'audio';
    mediaUrl = (att.payload && att.payload.url) || '';
  }

  if (!userMessage && mediaType === 'text') return [];

  const sessionId = 'fb_' + customerPsid;

  return [{
    json: {
      pageId,
      senderId: customerPsid,
      isComment: false,
      isEcho,
      commentId: '',
      sessionId,
      userMessage,
      mediaType,
      mediaUrl
    }
  }];
}

// ── Page feed comment ──
if (change && change.field === 'feed' && change.value && change.value.item === 'comment' && change.value.verb === 'add') {
  const v = change.value;
  const pageId = entry.id || '';
  const fromId = (v.from && v.from.id) || '';
  if (!fromId || fromId === pageId) return [];
  if (!v.message) return [];
  return [{
    json: {
      pageId,
      senderId: fromId,
      isComment: true,
      isEcho: false,
      commentId: v.comment_id || '',
      sessionId: 'fbc_' + (v.comment_id || fromId),
      userMessage: v.message,
      mediaType: 'text',
      mediaUrl: ''
    }
  }];
}

return [];

// ─────────────────────────────────────────────────────────────────────────────
// Build Brain Payload
// 1. Fetch Meta User Profile (name + profile_pic) for the sender.
// 2. Format profile data & create _upsert payload for PostgreSQL.
// 3. Return enriched payload for Execute Core AI Brain.
// ─────────────────────────────────────────────────────────────────────────────

const fbPayload   = $('Normalize FB Payload').item.json;
const integration = $('Fetch Integration').item.json;

const chatbotId   = integration.chatbotId;
const pageToken   = (integration.pageAccessToken || '').trim();
const sessionId   = fbPayload.sessionId;
const senderId    = (fbPayload.senderId || '').trim();
const isComment   = fbPayload.isComment;
const userMessage = fbPayload.userMessage;
const mediaType   = fbPayload.mediaType;
const mediaUrl    = fbPayload.mediaUrl;

let userName     = 'Facebook User';
let profilePhoto = '';

// ── Step 1: Fetch Meta user profile (Messenger Direct Messages only) ─────────
if (!isComment && senderId && pageToken) {
  const profileUrl = `https://graph.facebook.com/v20.0/${senderId}?fields=first_name,last_name,profile_pic&access_token=${pageToken}`;

  try {
    let profile = null;

    // 1. Try n8n's official httpRequest helper (bypasses sandbox limitations)
    if (typeof this !== 'undefined' && this.helpers && typeof this.helpers.httpRequest === 'function') {
      profile = await this.helpers.httpRequest({
        method: 'GET',
        url: profileUrl,
        json: true
      });
    } else if (typeof fetch === 'function') {
      // 2. Fallback to native fetch
      const res = await fetch(profileUrl);
      if (res.ok) {
        profile = await res.json();
      }
    }

    if (profile) {
      const firstName = (profile.first_name || '').trim();
      const lastName  = (profile.last_name  || '').trim();
      const fullName  = [firstName, lastName].filter(Boolean).join(' ');
      if (fullName) userName = fullName;
      if (profile.profile_pic) profilePhoto = profile.profile_pic;
    }
  } catch (err) {
    console.error('[Build Brain Payload] Profile fetch failed:', err.message || err);
  }
}

// ── Step 2: Prepare Upsert Data ──────────────────────────────────────────────
const upsertPayload = {
  chatbotId,
  sessionId,
  guestName: userName,
  profilePhoto: profilePhoto || ''
};

// ── Step 3: Return enriched payload ──────────────────────────────────────────
return [{
  json: {
    chatbotId,
    sessionId,
    customerName: userName,
    profilePhoto: profilePhoto || null,
    userMessage,
    mediaType,
    mediaUrl,
    platform: 'facebook',
    _upsert: upsertPayload
  }
}];
